using System;
using System.Diagnostics;

public class TraceContext
{
    public string TraceId { get; set; } = "";
    public string ParentSpanId { get; set; } = "";

    public static TraceContext? ParseTraceParent(string headerValue)
    {
        if (string.IsNullOrWhiteSpace(headerValue)) return null;

        string[] parts = headerValue.Split('-');
        if (parts.Length != 4 || parts[0] != "00")
        {
            return null;
        }

        if (parts[1].Length != 32 || parts[2].Length != 16)
        {
            return null;
        }

        return new TraceContext
        {
            TraceId = parts[1],
            ParentSpanId = parts[2]
        };
    }
}

public class Program
{
    public static void Main()
    {
        string rawHeader = "00-4bf92f3577b34da6a3ce929d0e0e4736-00f067aa0ba902b7-01";
        var context = TraceContext.ParseTraceParent(rawHeader);

        if (context != null)
        {
            Console.WriteLine($"[TraceContext Parsed]");
            Console.WriteLine($"Trace ID       : {context.TraceId}");
            Console.WriteLine($"Parent Span ID : {context.ParentSpanId}");
        }
        else
        {
            Console.WriteLine("Format header traceparent tidak valid!");
        }
    }
}
